const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakePoint = ee.Geometry.Point([136.5, -27.5]); // Lake Killamperpunna, SA
  const lakeRegion = lakePoint.buffer(5000); // 5km buffer to cover lake area

  const period1Start = '2025-06-15';
  const period1End = '2025-06-25';
  const period2Start = '2025-09-10';
  const period2End = '2025-09-20';

  // Function to get water pixel count for a given period
  async function getWaterPixelCount(startDate, endDate) {
    // Try Sentinel-2 first
    let s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(lakeRegion)
        .filterDate(startDate, endDate);

    let size = s2.size().getInfo();
    if (size === 0) {
      // Fallback to Landsat 9
      let ls9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
          .filterBounds(lakeRegion)
          .filterDate(startDate, endDate);
      size = ls9.size().getInfo();
      if (size === 0) {
        // Fallback to Landsat 8
        let ls8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
            .filterBounds(lakeRegion)
            .filterDate(startDate, endDate);
        size = ls8.size().getInfo();
        if (size === 0) {
          return {count: null, images: 0, collection: null, source: 'none'};
        } else {
          var collection = ls8;
          var source = 'Landsat8';
        }
      } else {
        var collection = ls9;
        var source = 'Landsat9';
      }
    } else {
      var collection = s2;
      var source = 'Sentinel2';
    }

    // Cloud masking function based on source
    function maskClouds(img) {
      if (source === 'Sentinel2') {
        // Sentinel-2: Use QA60 for clouds
        let qa = img.select('QA60');
        let cloudBitMask = 1 << 10;
        let cirrusBitMask = 1 << 11;
        let mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
        return img.updateMask(mask);
      } else {
        // Landsat 8/9: Use QA_PIXEL for clouds
        let qa = img.select('QA_PIXEL');
        let cloudMask = qa.bitwiseAnd(1 << 3).eq(0)  // cloud shadow
                         .and(qa.bitwiseAnd(1 << 4).eq(0))  // snow
                         .and(qa.bitwiseAnd(1 << 5).eq(0)); // clouds
        return img.updateMask(cloudMask);
      }
    }

    // Apply cloud masking and create median composite
    let composite = collection.map(maskClouds).median();

    // Compute NDWI for water detection
    let ndwi;
    if (source === 'Sentinel2') {
      // Sentinel-2: Green = B3, NIR = B8
      ndwi = composite.normalizedDifference(['B3', 'B8']);
    } else {
      // Landsat: Green = SR_B3, NIR = SR_B5
      ndwi = composite.normalizedDifference(['SR_B3', 'SR_B5']);
    }

    // Threshold NDWI > 0 for water
    let waterMask = ndwi.gt(0);

    // Count water pixels in the lake region
    let count = waterMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: lakeRegion,
      scale: 20,  // Use 20m scale for efficiency
      maxPixels: 1e9
    }).get('nd').getInfo();

    return {count: count, images: size, collection: collection, source: source};
  }

  // 2. Get water pixel counts for both periods
  let result1 = await getWaterPixelCount(period1Start, period1End);
  let result2 = await getWaterPixelCount(period2Start, period2End);

  // 3. Check for no data (C1)
  if (result1.images === 0 || result2.images === 0) {
    console.log(`June period images: ${result1.images} (${result1.source})`);
    console.log(`Sept period images: ${result2.images} (${result2.source})`);
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Check for no valid pixels (C2)
  if (result1.count === 0 || result2.count === 0) {
    console.log(`June water pixels: ${result1.count}`);
    console.log(`Sept water pixels: ${result2.count}`);
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Check for calculation failure (C3)
  if (result1.count === null || result2.count === null || 
      isNaN(result1.count) || isNaN(result2.count)) {
    console.log(`June result: ${result1.count}`);
    console.log(`Sept result: ${result2.count}`);
    console.log('<answer>C3</answer>');
    return;
  }

  // 6. Compare and output final answer
  console.log(`June (${result1.source}): ${result1.images} images, Water pixels: ${result1.count}`);
  console.log(`Sept (${result2.source}): ${result2.images} images, Water pixels: ${result2.count}`);
  console.log(`Change: ${result2.count - result1.count} pixels`);

  if (result2.count > result1.count) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
